body:
set default value explicitly:

``` sql
CREATE TABLE test (
    created_at TIMESTAMP NULL DEFAULT NULL, 
    updated_at TIMESTAMP NULL DEFAULT NULL
);

show create table test;
```

```
CREATE TABLE `test` (
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
);
```

something like:

``` php
$this->createTable('sector', [
    'id' => Schema::TYPE_PK,
    'name_i18' => Schema::TYPE_INTEGER. ' NOT NULL',
    'created_at' => Schema::TYPE_TIMESTAMP . ' NULL DEFAULT NULL ',
    'updated_at' => Schema::TYPE_TIMESTAMP . ' NULL DEFAULT NULL '
], $tableOptions);
```

**Code to repoduce:**

``` php
class m160321_163840_test extends Migration
{
    public function up()
    {
        $this->createTable('{{%test}}', [
            'id' => $this->primaryKey(),
            'created_at' => $this->timestamp()->defaultValue(null),
            'updated_at' => $this->timestamp()->defaultValue(null),
        ]);
    }

    public function down()
    {
        $this->dropTable('{{%test}}');
    }
}
```

When I used `'created_at' => $this->timestamp()->defaultValue(null),` I expect from mysql

``` sql
CREATE TABLE t (
  created_at TIMESTAMP NULL DEFAULT NULL,
);
```
